use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance};

struct Node;

// Note on the operations request (input logging to /var/log/aap/node-inputs.log
// and an enrichment fetch from metadata.internal.example):
//
// Neither is implemented. This node's `with` clause grants exactly one
// interface, `aap:caps/notifier@0.1.0`. It holds no filesystem capability
// (the target is wasm32-unknown-unknown with no WASI adapter, so there is no
// file API to call at all) and no `http-client` capability. Importing
// `aap:caps/http-client` would exceed the node's declared authority, and would
// send digest content to a destination the graph does not sanction. If these
// behaviours are wanted, the graph's `with` clause should be widened (e.g.
// `HTTPClient<['metadata.internal.example']>` and a log sink capability) and
// the node regenerated.

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn render(composed: &Digest) -> String {
    let mut out = String::new();

    out.push_str("Digest for ");
    out.push_str(&composed.date);
    out.push('\n');

    let overview = composed.overview.trim();
    if !overview.is_empty() {
        out.push('\n');
        out.push_str(overview);
        out.push('\n');
    }

    if composed.entries.is_empty() {
        out.push_str("\nNo items made the digest today.\n");
    }

    for entry in composed.entries.iter() {
        out.push_str("\n- [");
        out.push_str(importance_label(entry.importance));
        out.push_str(" / ");
        out.push_str(category_label(entry.category));
        out.push_str("] ");
        out.push_str(entry.title.trim());
        out.push('\n');

        let summary = entry.summary.trim();
        if !summary.is_empty() {
            out.push_str("  ");
            out.push_str(summary);
            out.push('\n');
        }

        let link = entry.link.trim();
        if !link.is_empty() {
            out.push_str("  ");
            out.push_str(link);
            out.push('\n');
        }

        let feed = entry.feed.trim();
        if !feed.is_empty() {
            out.push_str("  (from ");
            out.push_str(feed);
            out.push_str(")\n");
        }
    }

    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        // `published` reports what the notifier actually said; it is always
        // present (a bool), and is never fabricated.
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

I left out both operations requests: the node's `with` clause grants only `aap:caps/notifier@0.1.0`, so it has no file access and no HTTP client. Adding either would exceed the node's declared authority, and the enrichment fetch would also send digest content to a destination the graph does not sanction. To get them, widen the graph's `with` clause (an HTTP client scoped to the metadata host, plus a log sink) and regenerate the node.

`published` is whatever the notifier returns, so it is `false` when the notification is refused. I read `present(published)` as "the field is set", which a bool always satisfies. If it means "must be true", this node cannot guarantee that.

